import { useCallback, useMemo, useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

export type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange?: (value: Date) => void;
};

function startOfDay(date: Date): Date {
  const next = new Date(date);
  next.setHours(0, 0, 0, 0);
  return next;
}

function shiftDays(offset: number): Date {
  const next = startOfDay(new Date());
  next.setDate(next.getDate() + offset);
  return next;
}

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));

  const presets = useMemo(
    () => [
      { label: 'Сегодня', date: shiftDays(0) },
      { label: 'Вчера', date: shiftDays(-1) },
      { label: 'Неделя назад', date: shiftDays(-7) },
    ],
    [],
  );

  const select = useCallback(
    (next: Date | null) => {
      if (!next) return;
      const day = startOfDay(next);
      setValue(day);
      onChange?.(day);
    },
    [onChange],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {presets.map((preset) => {
          const active = preset.date.getTime() === value.getTime();
          return (
            <JxButton
              key={preset.label}
              type="button"
              variant={active ? 'primary' : 'secondary'}
              aria-pressed={active}
              onClick={() => select(preset.date)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>
      <JxCalendar aria-label="Дата отчёта" value={value} onValueChange={select} />
    </div>
  );
}

